// Program.cs in the modern ASP.NET Core gateway
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddReverseProxy()
    .LoadFromConfig(builder.Configuration.GetSection("ReverseProxy"));

var app = builder.Build();

app.MapReverseProxy();
app.MapGet("/", () => "Modern API Gateway");

app.Run();

// appsettings.json routes requests based on path
// Old path /api/orders -> legacy ASP.NET app
// New path /api/v2/orders -> modern ASP.NET Core app
// Over time, the new paths expand and the old paths shrink
{
  "ReverseProxy": {
    "Routes": [
      {
        "RouteId": "legacy-orders",
        "Match": { "Path": "/api/orders/{**catch-all}" },
        "ClusterId": "legacy-cluster"
      },
      {
        "RouteId": "modern-orders",
        "Match": { "Path": "/api/v2/orders/{**catch-all}" },
        "ClusterId": "modern-cluster"
      }
    ],
    "Clusters": {
      "legacy-cluster": { "Destinations": { "legacy": { "Address": "http://legacy-app/" } } },
      "modern-cluster": { "Destinations": { "modern": { "Address": "http://modern-app/" } } }
    }
  }
}

// Modern domain interface - clean and expressive
public interface ICustomerRepository
{
    Task<Customer> GetByIdAsync(Guid id, CancellationToken ct);
    Task SaveAsync(Customer customer, CancellationToken ct);
}

// Anti-corruption layer implementation
public class LegacyCustomerRepository : ICustomerRepository
{
    private readonly LegacyDbContext _legacyContext;

    public async Task<Customer> GetByIdAsync(Guid id, CancellationToken ct)
    {
        var dto = await _legacyContext.Cust_Table
            .Where(c => c.CUST_ID == id.ToString())
            .Select(c => new CustomerLegacyDto
            {
                Id = Guid.Parse(c.CUST_ID),
                FullName = c.FIRST_NAME + " " + c.LAST_NAME,
                Email = c.EMAIL_ADDR ?? "unknown"
            })
            .FirstAsync(ct);

        return MapToDomain(dto);
    }

    public async Task SaveAsync(Customer customer, CancellationToken ct)
    {
        var entity = new Cust_Table
        {
            CUST_ID = customer.Id.ToString(),
            FIRST_NAME = customer.FullName.Split(' ')[0],
            LAST_NAME = customer.FullName.Split(' ')[1],
            EMAIL_ADDR = customer.Email
        };
        await _legacyContext.Cust_Table.AddAsync(entity, ct);
        await _legacyContext.SaveChangesAsync(ct);
    }

    private Customer MapToDomain(CustomerLegacyDto dto) => new()
    {
        Id = dto.Id,
        FullName = dto.FullName,
        Email = dto.Email
    };
}
